use strcompress::{compress, decompress};

#[test]
fn test_compress_basic() {
    assert_eq!(compress("aabcccdddd"), "2ab3c4d");
}

#[test]
fn test_compress_no_runs() {
    assert_eq!(compress("abcd"), "abcd");
}

#[test]
fn test_compress_single_char() {
    assert_eq!(compress("aaaaa"), "5a");
}

#[test]
fn test_decompress_basic() {
    assert_eq!(decompress("2ab3c4d"), "aabcccdddd");
}

#[test]
fn test_round_trip() {
    let original = "aaabbbcccaaa";
    assert_eq!(decompress(&compress(original)), original);
}

